// TH15 v1.00b Extra stage 7 道中 w02
// 源: st07.ecl.txt:1134-1147 (MainSub01 排程入口)
//     661-684 (GirlD01 敌本体/移动)
//     686-709 (GirlD01_at 发弹 async)
// 卡帧0 = MainSub01 入口；开场120帧为合成外壳缓冲，之后按源 0/120/240/360 创建编队。

const TIME_LIMIT: int = 1324;
const OPENING_BUFFER: int = 120;

// 源 etSprite(0,19,3): 原 type19 -> TH15_BIG_BALL2 (基础半径8.5), 颜色3。
const TH15_BIG_BALL2: int = 656;

// ---- GirlD01_at (源 686-709) ----
// 源 689: wait(60)；然后 10 波，每波间隔 60 帧。
// 源 691 etAim(0,10) 固定交替层环；694 etAngle delta=0.05235988rad(3deg)；
// 695 etSpeed(0,2,2) 所有层同速2；693 etCount(0,10,5) = 10路×5层。
// mode10: angle = alpha + (-1)^q * (R(i)+H(5,q))，R(i)=(i*65536)/10，H=0,1,1,2,2 个3deg。
// 源 702-705 每波先 etAngle(alpha,3deg)、etOn，再 alpha-=0.261799rad(15deg)。
async sub girl_at() {
    wait(60);
    for shot in 0..10 {
        // alpha 从90deg开始，每波减15deg；按整度换算BAM，避免逐步截断累积。
        var alpha: int = ((90 - shot * 15) * 65536) / 360;
        var sx: fx = $self_x;
        var sy: fx = $self_y;
        for q in 0..5 {
            var sgn: int = 1;
            if q % 2 == 1 { sgn = -1; }
            var h: int = (q + 1) / 2;                 // H(5,q) = 0,1,1,2,2
            var hoff: int = ((h * 3) * 65536) / 360;  // 层偏角 h*3deg
            for i in 0..10 {
                var a: angle = (alpha + sgn * (((i * 65536) / 10) + hoff)) as angle;
                // 源 696 etEx type2(ANIM,a=1) 出生退位移 position -= 4*velocity；
                // 初速2 -> 沿弹角后退8px。出生减速/无判定窗口按已批准口径省略。
                // 源 697 type1048576(BRIGHT,a=1) 只影响混合，纯表现省略。
                _ = fire(TH15_BIG_BALL2, 3,
                         sx - 8fx * cos(a), sy - 8fx * sin(a),
                         2fx, a, none, none);
            }
        }
        wait(60);
    }
}

// ---- GirlD01 (源 661-684) ----
// 663-668 anm*/drop* 为表现与奖励，按公共口径省略。
// 669 setHurtbox(32,32) -> 受击半径16；670 setHitbox(24,24) -> 体碰半径12。
// 671 moveVel(pi/2,2.7) + 672 moveSpeedTime(60,1,0): 向下初速2.7，二次曲线减速到0。
// 673 @GirlD01_at async。
// 674 wait(240)；675 moveVel(-pi/2,0) + 676 moveSpeedTime(80,1,1): 转向上并加速到1。
// 677 wait(60)；678 跳入 440 -> 420 wait(1000) 无限循环（无 delete 可达）。
async sub girl_main() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 2.7fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN);
    spawn girl_at();
    wait(240);
    move_vel(0, 270deg, 0fx, EASE_LINEAR);
    move_speed(80, 1fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

// ---- MainSub01 (源 1134-1147): 7只 GirlD01，组间120帧 ----
// 源 1136/1138-1139/1141-1142/1144-1145 的 enmCreate 相对父位置；
// 外壳父为(0,0)，故目标直接用源 x/y。hp/score 按源1000/1000，普通掉落省略。
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -32fx, 1000, 0, 1000, 0, girl_main);
    wait(120);
    _ = spawn_enemy(-64fx, -32fx, 1000, 0, 1000, 0, girl_main);
    _ = spawn_enemy(64fx, -32fx, 1000, 0, 1000, 0, girl_main);
    wait(120);
    _ = spawn_enemy(-128fx, -32fx, 1000, 0, 1000, 0, girl_main);
    _ = spawn_enemy(128fx, -32fx, 1000, 0, 1000, 0, girl_main);
    wait(120);
    _ = spawn_enemy(-64fx, -32fx, 1000, 0, 1000, 0, girl_main);
    _ = spawn_enemy(64fx, -32fx, 1000, 0, 1000, 0, girl_main);
}

// ---- 独立无敌外壳 (validation.md) ----
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
